	float2 ts = 1.0 / float2(dstSize);
	float2 uv = (id.xy + 0.5) * ts;
	float2 h = ts * 0.5;
	if (pmode == 0) {
		// first level: from the HDR scene inside the view, exposed, fireflies tamed, soft threshold
		uv = (viewport.xy + uv * viewport.zw) * invTargetSize.xy;
		h = invTargetSize.xy;
	}
