		float thick = sceneD > 0 ? max(ViewDepth(sceneD) - ViewDepth(i.pos.z), 0) / 40.0 : 50.0;
		float3 sigma = (1 - saturate(m.emissive)) * 1.2 + 0.15;
		float3 Tr = exp(-sigma * thick);
